scripts.sum_of_squared_digits:
def solve(inputs: dict) -> float:
    n = inputs['N']
    k = inputs['K']

    for _ in range(k):
        # Calculate sum of squared digits
        digit_sum = sum(int(digit) ** 2 for digit in str(n))
        n = digit_sum

    return float(n)

scripts.accumulate_with_reset:
def solve(inputs: dict) -> float:
    values = inputs['VALUES']
    threshold = inputs['T']

    running_sum = 0

    for val in values:
        running_sum += val
        if running_sum > threshold:
            running_sum = 0

    return float(running_sum)

scripts.collatz_steps:
def solve(inputs: dict) -> float:
    n = inputs['N']
    k = inputs['K']

    for _ in range(k):
        if n % 2 == 0:
            n = n // 2
        else:
            n = 3 * n + 1

    return float(n)

